CREATE OR REPLACE FUNCTION public.calcular_total_recibo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE nuevo_total NUMERIC(10,2);
BEGIN
    SELECT COALESCE(SUM(total), 0) INTO nuevo_total FROM recibo_items WHERE recibo_id = COALESCE(NEW.recibo_id, OLD.recibo_id);
    UPDATE recibos SET total = nuevo_total WHERE id = COALESCE(NEW.recibo_id, OLD.recibo_id);
    RETURN COALESCE(NEW, OLD);
END; $function$

