CREATE OR REPLACE FUNCTION public.actualizar_mensaje_estado_recibo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE nuevo_contenido TEXT;
BEGIN
    IF OLD.estado != NEW.estado THEN
        CASE NEW.estado
            WHEN 'aceptado' THEN nuevo_contenido := 'Recibo aceptado: ' || NEW.titulo;
            WHEN 'rechazado' THEN nuevo_contenido := 'Recibo rechazado: ' || NEW.titulo;
                IF NEW.motivo_rechazo IS NOT NULL THEN nuevo_contenido := nuevo_contenido || ' - Motivo: ' || NEW.motivo_rechazo; END IF;
            ELSE nuevo_contenido := 'Recibo ' || NEW.estado || ': ' || NEW.titulo;
        END CASE;
        UPDATE mensajes_chat SET contenido = nuevo_contenido WHERE id = NEW.mensaje_id;
    END IF;
    RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.actualizar_precio_solicitud_recibo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE total_adicionales NUMERIC(10,2); precio_original NUMERIC(10,2);
BEGIN
    SELECT precio_base INTO precio_original FROM solicitudes_servicio WHERE id = NEW.solicitud_id;
    IF precio_original IS NULL THEN
        SELECT precio INTO precio_original FROM solicitudes_servicio WHERE id = NEW.solicitud_id;
        UPDATE solicitudes_servicio SET precio_base = precio_original WHERE id = NEW.solicitud_id;
    END IF;
    SELECT COALESCE(SUM(total), 0) INTO total_adicionales FROM recibos WHERE solicitud_id = NEW.solicitud_id AND estado = 'aceptado';
    UPDATE solicitudes_servicio SET precio_adicionales = total_adicionales, precio = precio_original + total_adicionales WHERE id = NEW.solicitud_id;
    RETURN NEW;
END; $function$

