CREATE OR REPLACE FUNCTION public.crear_mensaje_recibo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE chat_uuid UUID; mensaje_uuid UUID;
BEGIN
    SELECT id INTO chat_uuid FROM chats_solicitud WHERE solicitud_id = NEW.solicitud_id;
    IF chat_uuid IS NULL THEN INSERT INTO chats_solicitud (solicitud_id) VALUES (NEW.solicitud_id) RETURNING id INTO chat_uuid; END IF;
    INSERT INTO mensajes_chat (chat_id, remitente_id, rol_remitente, tipo_mensaje, recibo_id, contenido)
    VALUES (chat_uuid, NEW.proveedor_id, 'proveedor', 'recibo', NEW.id, 'Nuevo recibo: ' || NEW.titulo) RETURNING id INTO mensaje_uuid;
    UPDATE recibos SET mensaje_id = mensaje_uuid WHERE id = NEW.id;
    RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.sync_ticket_seq()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.ticket IS NOT NULL THEN
    PERFORM setval('ticket_seq',
                   GREATEST(NEW.ticket, (SELECT last_value FROM ticket_seq)));
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.crear_chat_al_asignar_proveedor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.profesional_id IS DISTINCT FROM NEW.profesional_id AND NEW.profesional_id IS NOT NULL THEN
        INSERT INTO chats_solicitud (solicitud_id) VALUES (NEW.id) ON CONFLICT (solicitud_id) DO NOTHING;
        DELETE FROM mensajes_chat WHERE chat_id = (SELECT id FROM chats_solicitud WHERE solicitud_id = NEW.id);
    END IF;
    RETURN NEW;
END; $function$

